import heapq

def func(arr, k):
    # Create a dictionary to store the frequency of each integer
    freq_dict = {}

    # Iterate through all the lists and update the frequency dictionary
    for lst in arr:
        for num in lst:
            if num in freq_dict:
                freq_dict[num] += 1
            else:
                freq_dict[num] = 1

    # Use a min-heap to keep track of the top k frequent integers
    min_heap = []
    for num, freq in freq_dict.items():
        if len(min_heap) < k:
