    num_str = str(n)

    # Find the length of the number
    length = len(num_str)

    # Check if the number is already a palindrome
    if num_str == num_str[::-1]:
        # If it's a palindrome, increment the last digit by 1
        for i in range(length - 1, -1, -1):
            if num_str[i] != '9':
                num_str[i] = str(int(num_str[i]) + 1)
                break
        else:
            # If all digits are 9, prepend a 1 and add a 0 at the end
            return int('1' + '0' * (length - 1))

    # If not a palindrome, find the next smallest palindrome
    for i in range(length - 2, -1, -1):
        if num_str[i] < '9':
            num_str[i] = str(int(num_str[i]) + 1)
            num_str[i+1:] = '0' * (length - i - 1)
            return int(num_str)

    # If all digits are 9, prepend a 1 and add a 0 at the end
    return int('1' + '0' * (length - 1))
